#Requires -Version 7.0
# Review-receipt helper: parse + PSScriptAnalyzer-gate a target review script, then run it.
[CmdletBinding()]
param(
    [Parameter(Mandatory)][string]$Target,
    [string[]]$TargetArgs = @()
)
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

$full = (Resolve-Path -LiteralPath $Target).ProviderPath
$tokens = $null
$parseErrors = $null
[void][System.Management.Automation.Language.Parser]::ParseFile($full, [ref]$tokens, [ref]$parseErrors)
if ($parseErrors -and $parseErrors.Count -gt 0) {
    $parseErrors | ForEach-Object { Write-Output ("PARSE-ERROR: {0} line {1}" -f $_.Message, $_.Extent.StartLineNumber) }
    throw "Parser errors in $full"
}
$analyzer = Get-Module -ListAvailable -Name PSScriptAnalyzer | Select-Object -First 1
if (-not $analyzer) {
    Write-Output 'ANALYZER: PSScriptAnalyzer not installed; parser check only.'
}
else {
    Import-Module PSScriptAnalyzer
    $findings = @(Invoke-ScriptAnalyzer -Path $full -Severity Warning, Error)
    Write-Output ("ANALYZER: {0} {1} findings={2}" -f $analyzer.Version, (Split-Path -Leaf $full), $findings.Count)
    foreach ($f in $findings) { Write-Output ("ANALYZER-FINDING: {0} {1} line {2}: {3}" -f $f.Severity, $f.RuleName, $f.Line, $f.Message) }
    $blocking = @($findings | Where-Object { $_.RuleName -notin @('PSAvoidUsingWriteHost') })
    if ($blocking.Count -gt 0) { throw 'Analyzer findings must be fixed before running.' }
}
Write-Output ("RUN-START: {0}" -f (Get-Date -Format s))
& $full @TargetArgs
Write-Output ("RUN-END: {0}" -f (Get-Date -Format s))

