1	<#
2	.SYNOPSIS
3	    Resolve the workspace-scoped PowerShell plugin cache directory.
4	.DESCRIPTION
5	    Runtime state belongs to the active workspace, never to the installed
6	    plugin checkout. The returned path is <workspace>/.mcpServer/<agent>.
7	
8	    Precedence:
9	      1. MCP_CACHE_DIR_OVERRIDE for an explicit test or recovery override.
10	      2. The workspace marker found from the explicit or active start path.
11	      3. MCP/host workspace environment variables as a markerless fallback.
12	 #>
13	
14	$script:ResolveCacheDirScriptDir = Split-Path -Parent $MyInvocation.MyCommand.Path
15	
16	function Get-McpCacheAgentKey {
17	    [CmdletBinding()]
18	    param()
19	
20	    # FR-MCP-SESSIONLIFE-002: inherited Grok variables must not move a Codex
21	    # plugin into the Grok cache namespace.
22	    $inheritedAgent = @($env:PLUGIN_AGENT_NAME, $env:MCP_AGENT_NAME) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | Select-Object -First 1
23	    if ($env:MCP_PLUGIN_HOST -match '^(?i:codex)$' -and $inheritedAgent -match '(?i)grok') {
24	        return 'codex'
25	    }
26	
27	    $agent = @(
28	        $env:MCP_AGENT_NAME,
29	        $env:PLUGIN_AGENT_NAME,
30	        $env:PLUGIN_AGENT_DEFAULT,
31	        $env:MCP_PLUGIN_HOST
32	    ) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | Select-Object -First 1
33	
34	    if (-not $agent) { return 'default' }
35	
36	    switch ($agent.Trim().ToLowerInvariant()) {
37	        'claude' { return 'claude' }
38	        'claudecode' { return 'claude' }
39	        'claude-code' { return 'claude' }
40	        'claudecowork' { return 'cowork' }
41	        'claude-cowork' { return 'cowork' }
42	        'codex' { return 'codex' }
43	        'copilot' { return 'copilot' }
44	        'grok' { return 'grok' }
45	        'grokcode' { return 'grok' }
46	        'grok-code' { return 'grok' }
47	        'cline' { return 'cline' }
48	        'cline-v2' { return 'cline' }
49	        'opencode' { return 'opencode' }
50	        'open-code' { return 'opencode' }
51	    }
52	
53	    $key = ($agent.Trim() -replace '[^A-Za-z0-9]+', '-').Trim('-').ToLowerInvariant()
54	    if (-not $key) { return 'default' }
55	    return $key
56	}
57	
58	function Get-McpPluginRoot {
59	    if ($env:MCP_PLUGIN_ROOT) { return $env:MCP_PLUGIN_ROOT }
60	    if ($env:CLAUDE_PLUGIN_ROOT) { return $env:CLAUDE_PLUGIN_ROOT }
61	    return (Split-Path -Parent $script:ResolveCacheDirScriptDir)
62	}
63	
64	function Join-McpWorkspaceCachePath {
65	    param([Parameter(Mandatory)][string]$WorkspacePath)
66	
67	    return (Join-Path (Join-Path $WorkspacePath '.mcpServer') (Get-McpCacheAgentKey))
68	}
69	
70	function Get-McpBackgroundScopeKey {
71	    <#
72	    .SYNOPSIS
73	        TR-MCP-PLUGIN-013 AC-005 (PLAN-SESSIONTRIAGEFIX-001 D3): the identity of a background host: MCP_SUBAGENT_ID, else GROK_SUBAGENT_ID,
74	        else the hook payload's session_id. None when there is none or when it equals the agentSessionId recorded for the root, because
75	        then the prompt is the root host's own.
76	    #>
77	    [CmdletBinding()]
78	    param(
79	        [string]$PayloadSessionId,
80	        [string]$RootAgentSessionId
81	    )
82	
83	    $key = @($env:MCP_SUBAGENT_ID, $env:GROK_SUBAGENT_ID, $PayloadSessionId) |
84	        Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | Select-Object -First 1
85	    if ([string]::IsNullOrWhiteSpace($key)) { return $null }
86	    $key = $key.Trim()
87	    if (-not [string]::IsNullOrWhiteSpace($RootAgentSessionId) -and
88	        [string]::Equals($key, $RootAgentSessionId.Trim(), [System.StringComparison]::Ordinal)) {
89	        return $null
90	    }
91	    return $key
92	}
93	
94	function Join-McpBackgroundScopePath {
95	    <#
96	    .SYNOPSIS
97	        TR-MCP-PLUGIN-013 AC-005 (D3): the cache folder of one background host, <cache>/background/<key>. A key with characters other than
98	        letters, digits, dot, underscore and hyphen, or longer than 96 characters, is made file-safe and suffixed with a hash of the
99	        original, so two keys never share a folder.
100	    #>
101	    [CmdletBinding()]
102	    param(
103	        [Parameter(Mandatory)][string]$CacheDir,
104	        [Parameter(Mandatory)][string]$Key
105	    )
106	
107	    $safe = ($Key -replace '[^A-Za-z0-9._-]+', '-').Trim('-', '.')
108	    if ($safe -cne $Key -or $safe.Length -gt 96) {
109	        $hash = [System.Convert]::ToHexString([System.Security.Cryptography.SHA256]::HashData([System.Text.Encoding]::UTF8.GetBytes($Key))).Substring(0, 12).ToLowerInvariant()
110	        if ($safe.Length -gt 80) { $safe = $safe.Substring(0, 80) }
111	        $safe = if ($safe) { "$safe-$hash" } else { $hash }
112	    }
113	    return (Join-Path (Join-Path $CacheDir 'background') $safe)
114	}
115	
116	function Resolve-McpBackgroundScopeCacheDir {
117	    <#
118	    .SYNOPSIS
119	        TR-MCP-PLUGIN-013 AC-005 (D3): the cache a session-log verb the agent calls itself uses. With no MCP_CACHE_DIR_OVERRIDE and with
120	        MCP_SUBAGENT_ID or GROK_SUBAGENT_ID set, that agent's background folder when it holds a current-turn.yaml; otherwise CacheDir.
121	        Those two are the only host identities an agent's own calls carry.
122	    #>
123	    [CmdletBinding()]
124	    param([Parameter(Mandatory)][string]$CacheDir)
125	
126	    if ($env:MCP_CACHE_DIR_OVERRIDE) { return $CacheDir }
127	    $key = @($env:MCP_SUBAGENT_ID, $env:GROK_SUBAGENT_ID) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | Select-Object -First 1
128	    if ([string]::IsNullOrWhiteSpace($key)) { return $CacheDir }
