208	function Get-McpFailsafeFileSha256Hex {
209	    <#
210	    .SYNOPSIS
211	        SHA-256 of a file as uppercase hex, used for failsafe queue migration.
212	    #>
213	    [CmdletBinding()]
214	    param([Parameter(Mandatory)][string]$Path)
215	
216	    $sha = [System.Security.Cryptography.SHA256]::Create()
217	    try {
218	        $stream = [System.IO.File]::OpenRead($Path)
219	        try {
220	            $hash = $sha.ComputeHash($stream)
221	            return (([BitConverter]::ToString($hash) -replace '-', ''))
222	        } finally {
223	            $stream.Dispose()
224	        }
225	    } finally {
226	        $sha.Dispose()
227	    }
228	}
