370	function Get-McpFailsafeDir {
371	    <#
372	    .SYNOPSIS
373	        TR-MCP-REPL-016: resolves the V4 failsafe pending directory.
374	    .DESCRIPTION
375	        Single source of truth for the queue location so the writer (repl-invoke),
376	        the drain, and the status reporter all agree with
377	        FilesystemSessionLogPersistenceStrategy:
378	        {workspace}/.mcpServer/failsafe/{agent}/workspaces/{workspace-key}/pending/.
379	        MCPSERVER_FAILSAFE_DIR and MCP_FAILSAFE_DIR override for tests and recovery.
380	        Legacy {workspace}/.mcpServer/{agent}/failsafe YAML is migrated by checksum
381	        match then source delete.
382	    #>
383	    [CmdletBinding()]
384	    param([string]$StartPath)
385	
386	    if ($env:MCPSERVER_FAILSAFE_DIR) { return $env:MCPSERVER_FAILSAFE_DIR }
387	    if ($env:MCP_FAILSAFE_DIR) { return $env:MCP_FAILSAFE_DIR }
388	
389	    # FR-MCP-SESSIONLIFE-003: a cache override is the supported markerless
390	    # recovery target. Keep the write-ahead queue beside it when no workspace
391	    # root can be resolved, so title and submit calls are not reported lost
392	    # before the server is attempted. An explicit failsafe override above
393	    # still wins, including a non-directory used to prove a lost write.
394	    try {
395	        $workspace = Resolve-McpFailsafeWorkspacePath -StartPath $StartPath
396	    } catch {
397	        $override = $env:MCP_CACHE_DIR_OVERRIDE
398	        if ($override -and (Test-Path -LiteralPath $override -PathType Container)) {
399	            $overridePending = Join-Path $override 'failsafe-pending'
400	            [void][System.IO.Directory]::CreateDirectory($overridePending)
401	            return $overridePending
402	        }
403	
404	        throw
405	    }
406	    $agent = Get-McpFailsafeAgentSegment
407	    $key = Get-McpFailsafeWorkspaceKey -WorkspacePath $workspace
408	    $pending = Join-Path $workspace (Join-Path '.mcpServer' (Join-Path 'failsafe' (Join-Path $agent (Join-Path 'workspaces' (Join-Path $key 'pending')))))
409	    [void][System.IO.Directory]::CreateDirectory($pending)
410	    Invoke-McpFailsafeLegacyQueueMigration -WorkspacePath $workspace -PendingDir $pending
411	    return $pending
412	}
