509	function Set-McpPluginSameVolumeTemp {
510	    <#
511	    .SYNOPSIS
512	        FR-MCP-TEMPVOL-001 / TR-MCP-TEMPVOL-001: align process TEMP and TMP to the target volume.
513	    .DESCRIPTION
514	        When TEMP/TMP are on a different volume than TargetPath, sets both to a writable
515	        directory on the target volume. Same-volume TEMP is left unchanged. A failed
516	        directory create does not mutate TEMP/TMP and returns Succeeded false with Error.
517	    #>
518	    [CmdletBinding()]
519	    param([Parameter(Mandatory)][string]$TargetPath)
520	
521	    $currentTemp = if (-not [string]::IsNullOrWhiteSpace($env:TEMP)) {
522	        $env:TEMP
523	    } elseif (-not [string]::IsNullOrWhiteSpace($env:TMP)) {
524	        $env:TMP
525	    } else {
526	        [System.IO.Path]::GetTempPath()
527	    }
528	
529	    $targetRoot = Get-McpPathVolumeRoot -Path $TargetPath
530	    $tempRoot = Get-McpPathVolumeRoot -Path $currentTemp
531	    if ($targetRoot -and $tempRoot -and $targetRoot.Equals($tempRoot, [System.StringComparison]::OrdinalIgnoreCase)) {
532	        return (New-McpPluginTempAlignmentResult -Succeeded $true -Changed $false -TempPath $currentTemp)
533	    }
534	
535	    try {
536	        $alignedDir = Get-McpPluginWorkspaceTempDirectory -TargetPath $TargetPath
537	        [void][System.IO.Directory]::CreateDirectory($alignedDir)
538	        $probe = Join-Path $alignedDir ('.write-probe-' + [guid]::NewGuid().ToString('N'))
539	        [System.IO.File]::WriteAllText($probe, 'ok')
540	        [System.IO.File]::Delete($probe)
541	    } catch {
542	        return (New-McpPluginTempAlignmentResult -Succeeded $false -Changed $false -TempPath $currentTemp -ErrorMessage ('Unable to create writable TEMP on the workspace volume: ' + $_.Exception.Message))
543	    }
544	
545	    $resolved = [System.IO.Path]::GetFullPath($alignedDir)
546	    $env:TEMP = $resolved
547	    $env:TMP = $resolved
548	    [Environment]::SetEnvironmentVariable('TEMP', $resolved, 'Process')
549	    [Environment]::SetEnvironmentVariable('TMP', $resolved, 'Process')
550	    return (New-McpPluginTempAlignmentResult -Succeeded $true -Changed $true -TempPath $resolved)
551	}
