553	function Invoke-McpPluginReplacementMove {
554	    <#
555	    .SYNOPSIS
556	        FR-MCP-TEMPVOL-001: replacement move that never reports success when the destination is unchanged.
557	    .DESCRIPTION
558	        Cross-volume File.Move is refused with a visible Error. Exceptions and missing
559	        destinations also return Succeeded false. Preview-without-apply cannot look like success.
560	    #>
561	    [CmdletBinding()]
562	    param(
563	        [Parameter(Mandatory)][string]$SourcePath,
564	        [Parameter(Mandatory)][string]$DestinationPath
565	    )
566	
567	    $failed = {
568	        param([string]$Message)
569	        return [pscustomobject]@{
570	            Succeeded = $false
571	            Error = $Message
572	            DestinationUnchanged = $true
573	        }
574	    }
575	
576	    $srcRoot = $null
577	    $dstRoot = $null
578	    try { $srcRoot = Get-McpPathVolumeRoot -Path $SourcePath } catch { $srcRoot = $null }
579	    try { $dstRoot = Get-McpPathVolumeRoot -Path $DestinationPath } catch { $dstRoot = $null }
580	
581	    if ([string]::IsNullOrWhiteSpace($srcRoot) -or [string]::IsNullOrWhiteSpace($dstRoot)) {
582	        return (& $failed 'replacement move refused: source or destination volume could not be resolved')
583	    }
584	
585	    if (-not $srcRoot.Equals($dstRoot, [System.StringComparison]::OrdinalIgnoreCase)) {
586	        return (& $failed 'cross-volume replacement move refused: TEMP/TMP must be on the destination volume')
587	    }
588	
589	    try {
590	        if (-not (Test-Path -LiteralPath $SourcePath -PathType Leaf)) {
591	            return (& $failed 'replacement move failed: source file is missing')
592	        }
593	
594	        $destDir = Split-Path -Parent $DestinationPath
595	        if ($destDir -and -not (Test-Path -LiteralPath $destDir -PathType Container)) {
596	            return (& $failed 'replacement move failed: destination directory is missing')
597	        }
598	
599	        [System.IO.File]::Move($SourcePath, $DestinationPath, $true)
600	    } catch {
601	        return (& $failed ('replacement move failed: ' + $_.Exception.Message))
602	    }
603	
604	    if (-not (Test-Path -LiteralPath $DestinationPath -PathType Leaf)) {
605	        return (& $failed 'replacement move failed: destination is missing after move')
606	    }
607	
608	    return [pscustomobject]@{
609	        Succeeded = $true
610	        Error = $null
611	        DestinationUnchanged = $false
612	    }
613	}
