#Requires -Version 7.0
# Review step 2: locate the Claude plugin cache/turn state for this workspace (read-only, redacted).
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
$ws = '<repo>'
$root = Join-Path $ws '.mcpServer'
Write-Output ("LOCAL-TIME: {0}" -f (Get-Date -Format s))
Get-ChildItem -LiteralPath $root -Force | ForEach-Object { Write-Output ("DIR .mcpServer/{0}" -f $_.Name) }
foreach ($candidate in @('claude', 'claudecode', 'ClaudeCode')) {
    $dir = Join-Path $root $candidate
    if (Test-Path -LiteralPath $dir) {
        Get-ChildItem -LiteralPath $dir -Force -Recurse -Depth 1 | ForEach-Object {
            Write-Output ("FILE {0} {1} {2}" -f $_.FullName.Substring($ws.Length), $_.Length, $_.LastWriteTime.ToString('s'))
        }
        foreach ($name in @('session-state.yaml', 'current-turn.yaml')) {
            $p = Join-Path $dir $name
            if (Test-Path -LiteralPath $p) {
                Write-Output "---- $candidate/$name"
                $t = Get-Content -LiteralPath $p -Raw
                $t = [regex]::Replace($t, '(?im)^(\s*(api[_-]?key|token|secret|password)\s*:\s*).+$', '$1<redacted>')
                Write-Output $t
            }
        }
    }
}
$pluginsDir = '<home>/.claude/plugins'
if (Test-Path -LiteralPath $pluginsDir) {
    Get-ChildItem -LiteralPath $pluginsDir -Recurse -Filter 'plugin.json' -Depth 6 -ErrorAction SilentlyContinue |
        Where-Object { $_.FullName -match 'mcpserver' } |
        ForEach-Object {
            $m = Get-Content -LiteralPath $_.FullName -Raw | ConvertFrom-Json
            Write-Output ("INSTALLED-PLUGIN {0} name={1} version={2}" -f $_.FullName, $m.name, $m.version)
        }
}

