1	<#
2	.SYNOPSIS
3	    Sends a YAML request envelope through the PowerShell MCP runtime.
4	.DESCRIPTION
5	    Constructs a YAML envelope and routes it through the configured
6	    PowerShell MCP invocation path.
7	
8	    Translation shim: workflow.sessionlog.* methods are not server routes
9	    — the dispatcher rejects them as method_not_found. They are plugin-
10	    local verbs that update cache/current-turn.yaml so the Stop hook can
11	    verify completion, and persist a session-log turn via the real
12	    client.SessionLog.SubmitAsync route.
13	
14	    Two usage modes:
15	      1. Script entry: pwsh -File repl-invoke.ps1 -Method <m> [-ParamsPath <file> | -ParamsYaml <y>]
16	         A launcher in another process passes -ParamsPath (repl-params-transfer.ps1): a Windows command line
17	         is limited to 32,767 characters, so params text never travels as an argument
18	         (triage-report-821fe2da58284b4ea21604cb2da2fccb). -ParamsYaml remains for in-process callers.
19	      2. Dot-source for Invoke-ReplMethod cmdlet:
20	             . .\repl-invoke.ps1
21	             Invoke-ReplMethod -Method workflow.sessionlog.completeTurn ...
22	#>
23	[CmdletBinding()]
24	param(
25	    [string]$Method,
26	    [string]$ParamsYaml = '',
27	    [string]$ParamsPath = ''
28	)
29	
30	$ErrorActionPreference = 'Stop'
31	
32	. (Join-Path $PSScriptRoot 'repl-params-transfer.ps1')
33	if ($PSBoundParameters.ContainsKey('ParamsPath')) {
34	    if ($PSBoundParameters.ContainsKey('ParamsYaml')) {
35	        throw 'repl-invoke.ps1: pass -ParamsPath or -ParamsYaml, not both.'
36	    }
37	    $ParamsYaml = Read-McpReplParamsFile -Path $ParamsPath
38	}
39	
40	$shimModule = Join-Path $PSScriptRoot 'McpPluginShim.psm1'
41	Import-Module $shimModule -Force -ErrorAction Stop
42	$shimCommand = Get-Command New-McpPluginTurnUpsertRequest -ErrorAction Stop
43	if (-not $shimCommand.Parameters.ContainsKey('ProcessingDialog')) {
44	    Remove-Module McpPluginShim -Force -ErrorAction SilentlyContinue
45	    Import-Module $shimModule -Force -ErrorAction Stop
46	    $shimCommand = Get-Command New-McpPluginTurnUpsertRequest -ErrorAction Stop
47	    if (-not $shimCommand.Parameters.ContainsKey('ProcessingDialog')) {
48	        throw 'McpPluginShim.psm1 is stale or invalid because New-McpPluginTurnUpsertRequest lacks ProcessingDialog.'
49	    }
50	}
51	. (Join-Path $PSScriptRoot 'yaml-object-mutation.ps1')
52	. (Join-Path $PSScriptRoot 'agent-runtime-header.ps1')
53	. (Join-Path $PSScriptRoot 'classified-error.ps1')
54	Import-McpYamlSerializer
55	. (Join-Path $PSScriptRoot 'marker-resolver.ps1')
56	
57	$script:ReplInvokePluginRoot = if ($env:MCP_PLUGIN_ROOT) {
58	    $env:MCP_PLUGIN_ROOT
59	} else {
60	    Split-Path -Parent $PSScriptRoot
61	}
62	
63	# Agent for per-agent REPL cache and isolation. Must be passed to every qbrain-ai-repl call.
64	# Keep this precedence aligned with the shell resolve-cache-dir counterpart and MarkerFileClientOptionsResolver.ResolveAgentKey.
65	$script:AgentName = if ($env:MCP_AGENT_NAME) { $env:MCP_AGENT_NAME }
66	                   elseif ($env:PLUGIN_AGENT_NAME) { $env:PLUGIN_AGENT_NAME }
67	                   elseif ($env:PLUGIN_AGENT_DEFAULT) { $env:PLUGIN_AGENT_DEFAULT }
68	                   elseif ($env:MCP_PLUGIN_HOST) { $env:MCP_PLUGIN_HOST }
69	                   else { 'default' }
70	
71	# FR-MCP-SESSIONLIFE-002: Codex keeps its audit identity when a host process
72	# inherits Grok agent variables. Other hosts keep the existing precedence.
73	if ($env:MCP_PLUGIN_HOST -match '^(?i:codex)$' -and $script:AgentName -match '(?i)grok') {
74	    $script:AgentName = 'Codex'
75	}
76	
77	function Get-ReplCanonicalAgentName {
78	    # TR-MCP-REPL-011: map the resolved agent (which can fall back to lowercase 'default' or a
79	    # lowercase host key like 'claude-code') to a PascalCase source type so composed session ids
80	    # satisfy the server regex ^[A-Z][A-Za-z0-9]*-... (BUG-TRIAGE-085).
81	    param([string]$AgentName)
82	
83	    if ([string]::IsNullOrWhiteSpace($AgentName)) { return 'ClaudeCode' }
84	
85	    switch (($AgentName.Trim().ToLowerInvariant() -replace '[^a-z0-9]', '')) {
86	        'claude'       { return 'ClaudeCode' }
87	        'claudecode'   { return 'ClaudeCode' }
88	        'claudecowork' { return 'ClaudeCowork' }
89	        'codex'        { return 'Codex' }
90	        'copilot'      { return 'Copilot' }
91	        'grok'         { return 'GrokCode' }
92	        'grokcode'     { return 'GrokCode' }
93	        'cline'        { return 'Cline' }
94	        'clinev2'      { return 'Cline' }
95	        'opencode'     { return 'OpenCode' }
96	    }
97	
98	    $parts = [regex]::Split($AgentName.Trim(), '[^A-Za-z0-9]+') | Where-Object { $_ }
99	    if (-not $parts) { return 'ClaudeCode' }
100	    return (-join ($parts | ForEach-Object { $_.Substring(0, 1).ToUpperInvariant() + $_.Substring(1) }))
101	}
102	
103	if (-not (Get-Command Resolve-McpCacheDir -ErrorAction SilentlyContinue) -or
104	    -not (Get-Command Get-McpFailsafeDir -ErrorAction SilentlyContinue)) {
105	    . (Join-Path $PSScriptRoot 'resolve-cache-dir.ps1')
106	}
107	
108	# Resolved lazily so per-call context (workspace / env) governs path. TR-MCP-PLUGIN-013 AC-005 (PLAN-SESSIONTRIAGEFIX-001 D3): a
109	# subagent's own session-log verbs (MCP_SUBAGENT_ID or GROK_SUBAGENT_ID set, no explicit override) reach its own background folder.
110	function script:Get-ReplInvokeCacheDir {
