282	    $cacheDir = Get-ReplInvokeCacheDir
283	    $rootSessionFile = Join-Path $cacheDir 'session-state.yaml'
284	    $rootState = if (Test-Path -LiteralPath $rootSessionFile) { Read-McpYamlObject -Path $rootSessionFile } else { $null }
285	    $rootSessionId = ''
286	    if ($rootState -is [System.Collections.IDictionary] -and $rootState.Contains('sessionId')) {
287	        $rootSessionId = [string]$rootState['sessionId']
288	    }
289	    $isChild = $false
290	    if ($params -is [System.Collections.IDictionary]) {
291	        $isChild = [bool]($params['background'] -or $params['child'] -or $params['sessionKey'])
292	    }
293	    if (-not $isChild -and -not [string]::IsNullOrWhiteSpace($rootSessionId) -and $rootSessionId -ne $sessionId) {
294	        $isChild = $true
295	    }
296	    $sessionFile = Write-ReplStickySessionState -CacheDir $cacheDir -RootSessionId $rootSessionId -SessionId $sessionId -Child:$isChild
297	    $state = Read-McpYamlObject -Path $sessionFile -Create
298	    if ($state -isnot [System.Collections.IDictionary]) { $state = [ordered]@{} }
299	    $state['status'] = 'verified'
