360	function Assert-ReplMarkerFresh {
361	    $workspace = Resolve-ReplWorkspaceDirectory
362	    $sessionFile = Join-Path (Get-ReplInvokeCacheDir) 'session-state.yaml'
363	
364	    try {
365	        $snapshot = Get-MarkerFileSnapshot -StartDir $workspace
366	        $state = Read-McpYamlObject -Path $sessionFile -Create
367	        if ($state -isnot [System.Collections.IDictionary]) {
368	            $state = [ordered]@{}
369	        }
370	
371	        $status = if ($state.Contains('status')) { [string]$state['status'] } else { '' }
372	        $cachedPath = if ($state.Contains('markerFilePath')) { [string]$state['markerFilePath'] } else { '' }
373	        $cachedWriteUtc = if ($state.Contains('markerLastWriteUtc')) { [string]$state['markerLastWriteUtc'] } else { '' }
374	        $cachedSessionId = if ($state.Contains('sessionId')) { [string]$state['sessionId'] } else { '' }
375	
376	        if ($status -eq 'verified' -and
377	            $cachedPath -eq $snapshot.markerFilePath -and
378	            $cachedWriteUtc -eq $snapshot.markerLastWriteUtc -and
379	            -not [string]::IsNullOrWhiteSpace($cachedSessionId)) {
380	            return $true
381	        }
382	
383	        if (-not (Invoke-FullBootstrap -StartDir $workspace)) {
384	            throw 'marker bootstrap failed'
385	        }
386	        $snapshot = Get-MarkerFileSnapshot -StartDir $workspace
387	
388	        $state['status'] = 'verified'
389	        if (-not $state.Contains('agent')) {
390	            $state['agent'] = $script:AgentName
391	        }
392	        if (-not $state.Contains('sessionId') -or [string]::IsNullOrWhiteSpace([string]$state['sessionId'])) {
393	            $state['sessionId'] = New-ReplPluginSessionId
394	        }
395	        $state['lastUpdated'] = (Get-Date).ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ')
396	        $state['markerFilePath'] = $snapshot.markerFilePath
397	        $state['markerLastWriteUtc'] = $snapshot.markerLastWriteUtc
398	        Write-McpYamlObject -Path $sessionFile -Document $state
399	        return $true
400	    } catch {
401	        $untrustedState = [ordered]@{
402	            status = 'MCP_UNTRUSTED'
403	            lastUpdated = (Get-Date).ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ')
404	        }
405	        try {
406	            $snapshot = Get-MarkerFileSnapshot -StartDir $workspace
407	            $untrustedState['markerFilePath'] = $snapshot.markerFilePath
408	            $untrustedState['markerLastWriteUtc'] = $snapshot.markerLastWriteUtc
409	        } catch {
410	        }
411	        Write-McpYamlObject -Path $sessionFile -Document $untrustedState
412	        [Console]::Error.WriteLine("MCP_UNTRUSTED: marker refresh failed before REPL request: $_")
413	        return $false
414	    }
415	}
