428	function Convert-ReplParamsYamlToObject {
429	    param([string]$ParamsYaml)
430	
431	    if (-not $ParamsYaml) { return $null }
432	
433	    $normalized = $ParamsYaml -replace "`r`n", "`n" -replace "`r", ""
434	    if ($normalized.TrimStart() -match '^[\{\[]') {
435	        return ($normalized | ConvertFrom-Json -Depth 100 -ErrorAction Stop)
436	    }
437	
438	    if (Get-Command ConvertFrom-Yaml -ErrorAction SilentlyContinue) {
439	        try {
440	            return ($normalized | ConvertFrom-Yaml -ErrorAction Stop)
441	        } catch {
442	            # Fall through to the local subset parser so plugin runtime remains
443	            # self-contained when the optional YAML module cannot parse input.
444	        }
445	    }
446	
447	    return (ConvertFrom-ReplYamlSubset -Text $normalized)
448	}
