450	function ConvertFrom-ReplYamlScalar {
451	    param([string]$Value)
452	
453	    $trimmed = $Value.Trim()
454	    if ($trimmed -eq '') { return '' }
455	    if ($trimmed -eq '{}') { return [ordered]@{} }
456	    if ($trimmed -eq '[]') { return @() }
457	    if ($trimmed -match '^(true|false)$') { return [bool]::Parse($trimmed) }
458	    if ($trimmed -match '^-?\d+$') { return [int64]$trimmed }
459	    if (($trimmed.StartsWith('"') -and $trimmed.EndsWith('"')) -or ($trimmed.StartsWith("'") -and $trimmed.EndsWith("'"))) {
460	        return $trimmed.Substring(1, $trimmed.Length - 2)
461	    }
462	
463	    return $trimmed
464	}
