480	function Read-ReplYamlBlock {
481	    param(
482	        [string[]]$Lines,
483	        [ref]$Index,
484	        [int]$Indent
485	    )
486	
487	    while ($Index.Value -lt $Lines.Count -and $Lines[$Index.Value].Trim() -eq '') {
488	        $Index.Value++
489	    }
490	
491	    if ($Index.Value -ge $Lines.Count) { return [ordered]@{} }
492	
493	    $first = $Lines[$Index.Value]
494	    $isList = (Get-ReplYamlIndent $first) -eq $Indent -and $first.Substring($Indent).TrimStart().StartsWith('- ')
495	    if ($isList) {
496	        $items = [System.Collections.Generic.List[object]]::new()
497	        while ($Index.Value -lt $Lines.Count) {
498	            $line = $Lines[$Index.Value]
499	            if ($line.Trim() -eq '') { $Index.Value++; continue }
500	            $currentIndent = Get-ReplYamlIndent $line
501	            if ($currentIndent -lt $Indent) { break }
502	            if ($currentIndent -ne $Indent) { break }
503	            $content = $line.Substring($Indent).TrimStart()
504	            if (-not $content.StartsWith('- ')) { break }
505	
506	            $itemText = $content.Substring(2).Trim()
507	            $Index.Value++
508	            if ($itemText -match '^([^:]+):\s*(.*)$') {
509	                $item = [ordered]@{}
510	                $key = $Matches[1].Trim()
511	                $value = $Matches[2]
512	                if ($value -eq '') {
513	                    $item[$key] = Read-ReplYamlBlock -Lines $Lines -Index $Index -Indent ($Indent + 2)
514	                } else {
515	                    $item[$key] = ConvertFrom-ReplYamlScalar $value
516	                }
517	
518	                while ($Index.Value -lt $Lines.Count) {
519	                    $nextLine = $Lines[$Index.Value]
520	                    if ($nextLine.Trim() -eq '') { $Index.Value++; continue }
521	                    $nextIndent = Get-ReplYamlIndent $nextLine
522	                    if ($nextIndent -le $Indent) { break }
523	                    $nextContent = $nextLine.Substring($nextIndent)
524	                    if ($nextContent -notmatch '^([^:]+):\s*(.*)$') { break }
525	                    $nextKey = $Matches[1].Trim()
526	                    $nextValue = $Matches[2]
527	                    $Index.Value++
528	                    if ($nextValue -eq '|') {
529	                        $item[$nextKey] = Read-ReplYamlLiteralBlock -Lines $Lines -Index $Index -Indent ($nextIndent + 2)
530	                    } elseif ($nextValue -eq '') {
531	                        $item[$nextKey] = Read-ReplYamlBlock -Lines $Lines -Index $Index -Indent ($nextIndent + 2)
532	                    } else {
533	                        $item[$nextKey] = ConvertFrom-ReplYamlScalar $nextValue
534	                    }
535	                }
536	
537	                $items.Add([pscustomobject]$item)
538	            } else {
539	                $items.Add((ConvertFrom-ReplYamlScalar $itemText))
540	            }
541	        }
542	
543	        return $items.ToArray()
544	    }
545	
546	    $map = [ordered]@{}
547	    while ($Index.Value -lt $Lines.Count) {
548	        $line = $Lines[$Index.Value]
549	        if ($line.Trim() -eq '') { $Index.Value++; continue }
550	        $currentIndent = Get-ReplYamlIndent $line
551	        if ($currentIndent -lt $Indent) { break }
552	        if ($currentIndent -gt $Indent) { break }
553	
554	        $content = $line.Substring($Indent)
555	        if ($content -notmatch '^([^:]+):\s*(.*)$') { $Index.Value++; continue }
556	        $key = $Matches[1].Trim()
557	        $value = $Matches[2]
558	        $Index.Value++
559	
560	        if ($value -eq '|') {
561	            $map[$key] = Read-ReplYamlLiteralBlock -Lines $Lines -Index $Index -Indent ($Indent + 2)
562	        } elseif ($value -eq '') {
563	            $map[$key] = Read-ReplYamlBlock -Lines $Lines -Index $Index -Indent ($Indent + 2)
564	        } else {
565	            $map[$key] = ConvertFrom-ReplYamlScalar $value
566	        }
567	    }
568	
569	    return [pscustomobject]$map
570	}
