572	function Read-ReplYamlLiteralBlock {
573	    param(
574	        [string[]]$Lines,
575	        [ref]$Index,
576	        [int]$Indent
577	    )
578	
579	    $items = [System.Collections.Generic.List[string]]::new()
580	    while ($Index.Value -lt $Lines.Count) {
581	        $line = $Lines[$Index.Value]
582	        if ($line.Trim() -ne '' -and (Get-ReplYamlIndent $line) -lt $Indent) { break }
583	        if ($line.Length -ge $Indent) {
584	            $items.Add($line.Substring($Indent))
585	        } else {
586	            $items.Add('')
587	        }
588	        $Index.Value++
589	    }
590	
591	    return ($items -join "`n").TrimEnd()
592	}
