631	function Get-ReplMethodTimeoutSeconds {
632	    # TR-MCP-REPL-012: per-method timeout. Long-running requirement/agent methods (which invoke
633	    # external CLIs and can take minutes) get an extended, env-configurable budget; everything else
634	    # keeps the short default so sessionlog calls fail fast (BUG-TRIAGE-072).
635	    param([Parameter(Mandatory)][string]$Method)
636	
637	    $default = if ($env:REPL_TIMEOUT) { [int]$env:REPL_TIMEOUT } else { 30 }
638	    $long = if ($env:REPL_LONG_TIMEOUT) { [int]$env:REPL_LONG_TIMEOUT } else { 300 }
639	    $helper = if ($env:REPL_HELPER_TIMEOUT) { [int]$env:REPL_HELPER_TIMEOUT } else { 120 }
640	
641	    if ($script:ReplFailsafeDraining -and $Method -eq 'client.SessionLog.SubmitAsync') {
642	        # TR-MCP-REPL-012 AC3 / TEST-MCP-195 AC5-7: drain SubmitAsync uses
643	        # REPL_FAILSAFE_DRAIN_TIMEOUT (default 120s), or REPL_TIMEOUT when greater.
644	        # Sessionlog workflow methods keep $default (30s). Nested drain stays deferred.
645	        $drain = if ($env:REPL_FAILSAFE_DRAIN_TIMEOUT) { [int]$env:REPL_FAILSAFE_DRAIN_TIMEOUT } else { 120 }
646	        $seconds = if ($default -gt $drain) { $default } else { $drain }
647	    } else {
648	        $seconds = switch -Wildcard ($Method) {
649	            'workflow.todo.analyzeRequirements'       { $long; break }
650	            'workflow.requirements.generateDocument'  { $long; break }
651	            'workflow.requirements.ingestDocument'    { $long; break }
652	            'workflow.requirements.analyze*'          { $long; break }
653	            'client.Requirements.Analyze*'            { $long; break }
654	            'workflow.agenthelp.submitTurn'           { $helper; break }
655	            default                                   { $default }
656	        }
657	    }
658	
659	    # TR-MCP-REPL-012 AC-001 (D1, triage-report-124a374c): inside a hook no call
660	    # may wait past the hook's deadline; outside a hook the timeout is unchanged.
661	    return (Get-ReplCappedTimeout -TimeoutSeconds $seconds -RemainingMs (Get-ReplHookTimeLeft))
662	}
