673	function Get-ReplCappedTimeout {
674	    # TR-MCP-REPL-012 AC-001 (D1): the lesser of the per-method timeout and the
675	    # whole seconds left before the hook deadline, so a slow or silent server ends
676	    # the call in time and the persist falls back to its write-ahead failsafe
677	    # record. 0 when less than one second is left: the call is then not started
678	    # (Invoke-ReplRawCore), because a call begun after the deadline would carry the
679	    # hook past its budget. Without a deadline the timeout is unchanged.
680	    param(
681	        [Parameter(Mandatory)][int]$TimeoutSeconds,
682	        [AllowNull()][Nullable[long]]$RemainingMs
683	    )
684	    if ($null -eq $RemainingMs) { return $TimeoutSeconds }
685	    return [int][Math]::Max(0, [Math]::Min([double]$TimeoutSeconds, [Math]::Floor([double]$RemainingMs / 1000)))
686	}
