706	function Invoke-ReplRawCore {
707	    param(
708	        [Parameter(Mandatory)][string]$Method,
709	        [string]$ParamsYaml = ''
710	    )
711	    if (-not (Assert-ReplMarkerFresh)) {
712	        return (New-McpPluginReplResult -Success $false -Output '' -Error 'MCP_UNTRUSTED: marker refresh failed before REPL request')
713	    }
714	
715	    $replCommand = Get-Command qbrain-ai-repl -ErrorAction SilentlyContinue
716	    if (-not $replCommand) {
717	        $replCommand = Get-Command mcpserver-repl -ErrorAction SilentlyContinue
718	    }
719	    $replExe = $null
720	    if ($env:MCP_REPL_EXECUTABLE -and (Test-Path -LiteralPath $env:MCP_REPL_EXECUTABLE)) {
721	        $replExe = $env:MCP_REPL_EXECUTABLE
722	    } elseif ($replCommand) {
723	        $replExe = [string]$replCommand.Source
724	    }
725	    if ([string]::IsNullOrWhiteSpace($replExe)) {
726	        return (New-McpPluginReplResult -Success $false -Output '' -Error 'qbrain-ai-repl or mcpserver-repl not found on PATH')
727	    }
728	
729	    $requestId = "req-$(Get-Date -AsUTC -Format 'yyyyMMddTHHmmssZ')-$((Get-Random -Maximum 0xFFFF).ToString('x4'))"
730	    $timeout = Get-ReplMethodTimeoutSeconds -Method $Method
731	    if ($timeout -le 0) {
732	        # TR-MCP-REPL-012 AC-001 (D1): under one second is left before the hook deadline, so the call is not
733	        # started; it fails as timed out and a persist keeps its write-ahead failsafe record as the fallback.
734	        return (New-McpPluginReplResult -Success $false -Output '' -Error "qbrain-ai-repl timed out after 0s: the hook deadline left no time to start $Method")
735	    }
736	
737	    # Build as an object and serialize to JSON so request envelopes keep a
738	    # single canonical shape across plugin hosts.
739	    $paramsObject = $null
740	    if ($ParamsYaml) {
741	        $paramsObject = Convert-ReplParamsYamlToObject -ParamsYaml $ParamsYaml
742	    }
743	    $request = New-McpPluginReplRequest -RequestId $requestId -Method $Method -Params $paramsObject
744	    $envelope = ConvertTo-McpPluginJson -InputObject $request -Depth 20 -Compress
745	
746	    try {
747	        $psi = [System.Diagnostics.ProcessStartInfo]::new()
748	        if ($replExe -match '\.(cmd|bat)$') {
749	            $psi.FileName = $env:ComSpec
750	            $psi.ArgumentList.Add('/c')
751	            $psi.ArgumentList.Add($replExe)
752	        } else {
753	            $psi.FileName = $replExe
754	        }
755	        $psi.ArgumentList.Add('--agent-stdio')
756	        $psi.ArgumentList.Add('--agent')
757	        $psi.ArgumentList.Add($script:AgentName)
758	        $psi.RedirectStandardInput = $true
759	        $psi.RedirectStandardOutput = $true
760	        # Do NOT redirect stderr: qbrain-ai-repl logs verbose 'info:' lines
761	        # to stderr, and an unread redirected stream blocks the child once
762	        # its pipe buffer fills (Windows ~4 KB), causing WaitForExit to hang.
763	        $psi.UseShellExecute = $false
764	        $psi.CreateNoWindow = $true
765	        Set-ReplProcessWorkspace -StartInfo $psi
766	        # qbrain-ai-repl writes UTF-8 (with BOM). Without explicit encoding,
767	        # PowerShell decodes as cp437 and BOM bytes (EF BB BF) become box-
768	        # drawing glyphs that break the '^type: error' regex anchor.
769	        $psi.StandardOutputEncoding = [System.Text.Encoding]::UTF8
770	
771	        $proc = [System.Diagnostics.Process]::Start($psi)
772	        $budget = [System.Diagnostics.Stopwatch]::StartNew()
773	        $envFile = Join-Path (Get-ReplInvokeCacheDir) "envelope-$requestId.tmp"
774	        [System.IO.File]::WriteAllText($envFile, $envelope, [System.Text.Encoding]::UTF8)
775	        $copyStream = [System.IO.File]::OpenRead($envFile)
776	        $copyTask = $copyStream.CopyToAsync($proc.StandardInput.BaseStream)
777	        $copyBudget = [int][Math]::Max(1, ($timeout * 1000) - $budget.ElapsedMilliseconds)
778	        if (-not $copyTask.Wait($copyBudget)) {
779	            try { $copyStream.Dispose() } catch { }
780	            try { $proc.Kill($true) } catch { }
781	            try { [void]$proc.WaitForExit(2000) } catch { }
782	            Remove-Item $envFile -ErrorAction SilentlyContinue
783	            return (New-McpPluginReplResult -Success $false -Output '' -Error "qbrain-ai-repl timed out after ${timeout}s")
784	        }
785	        $copyStream.Dispose()
786	        $proc.StandardInput.Close()
787	        Remove-Item $envFile -ErrorAction SilentlyContinue
788	
789	        # Drain stdout BEFORE waiting for exit. With a redirected pipe, the
790	        # child blocks on stdout writes once the pipe buffer (~4 KB on
791	        # Windows) fills, and WaitForExit then deadlocks. ReadToEndAsync
792	        # streams the buffer concurrently and resolves when the child closes
793	        # stdout (which happens at process exit).
794	        $readTask = $proc.StandardOutput.ReadToEndAsync()
795	        $readBudget = [int][Math]::Max(1, ($timeout * 1000) - $budget.ElapsedMilliseconds)
796	        if (-not $readTask.Wait($readBudget)) {
797	            try { $proc.Kill($true) } catch { }
798	            try { [void]$proc.WaitForExit(2000) } catch { }
799	            return (New-McpPluginReplResult -Success $false -Output '' -Error "qbrain-ai-repl timed out after ${timeout}s")
800	        }
801	        $output = $readTask.Result
802	        $exitBudget = [int][Math]::Max(1, ($timeout * 1000) - $budget.ElapsedMilliseconds)
803	        if (-not $proc.WaitForExit($exitBudget)) {
804	            try { $proc.Kill($true) } catch { }
805	            try { [void]$proc.WaitForExit(2000) } catch { }
806	            return (New-McpPluginReplResult -Success $false -Output '' -Error "qbrain-ai-repl timed out after ${timeout}s")
807	        }
808	
809	        # qbrain-ai-repl writes a UTF-8 BOM before the YAML doc and may
810	        # interleave logger 'info:' lines on stdout — strip BOM and ignore
811	        # leading log noise so the regex anchor matches the real header.
812	        $output = $output -replace "[\uFEFF]", ''
813	        $isError = $output -match '(?m)^type:\s*error\b'
814	        if ($proc.ExitCode -ne 0 -or $isError) {
815	            return (New-McpPluginReplResult -Success $false -Output $output -ExitCode $proc.ExitCode)
816	        }
817	        # TR-MCP-REPL-016: this is the first proof in the process that the backend
818	        # answers, so it is the safe moment to replay anything the failsafe queue
819	        # captured while it was unreachable. Guarded to run at most once.
820	        Invoke-ReplFailsafeDrainOnFirstSuccess
821	        return (New-McpPluginReplResult -Success $true -Output $output -ExitCode $proc.ExitCode)
822	    }
823	    catch {
824	        $caughtOutput = ''
825	        if (Get-Variable -Name output -Scope Local -ErrorAction SilentlyContinue) {
826	            $caughtOutput = [string]$output
827	        }
828	        $classified = ConvertTo-McpPluginClassifiedError -Output $caughtOutput -ErrorText $_.ToString()
829	        if ($classified.preserved) {
830	            return (New-McpPluginReplResult -Success $false -Output $caughtOutput -Error $classified.message)
831	        }
832	        return (New-McpPluginReplResult -Success $false -Output '' -Error $_.ToString())
833	    }
834	}
