import { createHash } from "node:crypto";
import { afterEach, expect, it, vi } from "vitest";

const database = vi.hoisted(() => ({ query: vi.fn(), release: vi.fn() }));
vi.mock("pg", () => ({ Pool: class {
  on() {}
  async connect() { return database; }
} }));
afterEach(() => { vi.unstubAllEnvs(); vi.resetModules(); });
const hash = (value: string) => createHash("sha256").update(value).digest("hex");
const guest = "g".repeat(43), admin = "a".repeat(43);
const profile = (kind: "guest" | "member") => ({ id: kind, version: 0, kind, providerSubject: kind === "member" ? "16146732" : null, alias: "Fixture", icon: "owl", publicLeaderboard: false, wins: 0, points: 0, earliestWinAt: null });

it("actual composition separates guest/admin token namespaces, strips guest roles and revokes admin independently", async () => {
  vi.stubEnv("WORDPAIRS_DATABASE_URL", "postgresql://fixture:fixture@localhost:5432/fixture");
  vi.stubEnv("WORDPAIRS_ORIGIN", "https://wordpairs.example.test");
  vi.stubEnv("WORDPAIRS_GITHUB_CLIENT_ID", "fixture-client");
  vi.stubEnv("WORDPAIRS_GITHUB_CLIENT_SECRET", "fixture-secret");
  vi.stubEnv("WORDPAIRS_ADMIN_PROFILE_IDS", "guest");
  const issued = new Map([[hash(guest), profile("guest")], [hash(`github-admin\u0000${admin}`), profile("member")]]);
  database.query.mockImplementation(async (sql: string, args: unknown[]) => {
    const digest = String(args[0]);
    if (sql.includes("identity_revoke")) return { rows: [{ response: issued.delete(digest) }] };
    if (!sql.includes("identity_session")) throw new Error("Unexpected fixture query");
    const current = issued.get(digest);
    return { rows: [{ response: current ? { profile: current, actor: { profileId: current.id, roles: ["admin"] } } : null }] };
  });
  const runtime = await import("../../src/infrastructure/runtime");
  const players = runtime.getIdentityService()!;
  const administrators = runtime.getAdminIdentityService()!;
  expect((await players.session(guest))).toMatchObject({ ok: true, value: { actor: { profileId: "guest", roles: ["player"] } } });
  expect((await administrators.session(guest)).ok).toBe(false);
  expect((await players.session(admin)).ok).toBe(false);
  expect((await administrators.session(admin))).toMatchObject({ ok: true, value: { profile: { kind: "member" } } });
  const { adminSession } = await import("../../src/web/admin-session");
  const request = (token: string) => new Request("https://wordpairs.example.test/api/admin/session", { headers: { Cookie: `wp_admin=${token}; wp_session=${guest}` } });
  expect((await adminSession(request(guest))).ok).toBe(false);
  expect(await adminSession(request(admin))).toMatchObject({ ok: true, value: { actor: { profileId: "member", roles: ["admin"] } } });
  // Even an incorrectly issued guest-shaped record cannot become administrator.
  issued.set(hash(`github-admin\u0000${guest}`), profile("guest"));
  expect((await adminSession(request(guest))).ok).toBe(false);
  // A formerly account-backed public game session is rejected in guest mode.
  issued.set(hash("m".repeat(43)), profile("member"));
  expect((await players.session("m".repeat(43))).ok).toBe(false);
  expect(runtime.oidcAvailable()).toBe(false);
  await administrators.logout(admin);
  expect((await administrators.session(admin)).ok).toBe(false);
  expect((await players.session(guest)).ok).toBe(true);
});

import { createHash } from "node:crypto";
import { describe, expect, it, vi } from "vitest";
import { GithubAdminProvider } from "../../src/infrastructure/github-admin";

const settings = { clientId: "fixture-client", clientSecret: "fixture-secret", redirectUri: "https://wordpairs.example.test/api/auth/github/callback" };
const challenge = { state: "s".repeat(43), nonce: "n".repeat(43), pkceVerifier: "v".repeat(43) };
const callback = { code: "fixture-code", state: challenge.state, expectedState: challenge.state, nonce: challenge.nonce, pkceVerifier: challenge.pkceVerifier };
describe("private GitHub administrator identity, isolated provider fixtures", () => {
  it("requests identity with state/S256 and exact callback without repository/email scopes", async () => {
    const result = await new GithubAdminProvider(settings).authorization(challenge);
    if (!result.ok) throw new Error("Authorization failed");
    const url = new URL(result.value);
    expect(url.origin + url.pathname).toBe("https://github.com/login/oauth/authorize");
    expect(Object.fromEntries(url.searchParams)).toMatchObject({ state: challenge.state, redirect_uri: settings.redirectUri,
      client_id: settings.clientId, login: "sharpninja", allow_signup: "false", code_challenge_method: "S256",
      code_challenge: createHash("sha256").update(challenge.pkceVerifier).digest("base64url") });
    expect(url.searchParams.has("scope")).toBe(false);
    expect(url.href).not.toContain(settings.clientSecret);
  });
  it("accepts only server-verified owner ID/login and discards provider credentials", async () => {
    const transport = vi.fn().mockResolvedValueOnce(Response.json({ token_type: "bearer", access_token: "provider-secret", refresh_token: "refresh-secret" }))
      .mockResolvedValueOnce(Response.json({ id: 16146732, login: "sharpninja", email: "private@example.test" }));
    const result = await new GithubAdminProvider(settings, transport).verify(callback);
    expect(result).toEqual({ ok: true, value: { issuer: "https://github.com", subject: "16146732" } });
    const tokenRequest = transport.mock.calls[0];
    expect(tokenRequest[0]).toBe("https://github.com/login/oauth/access_token");
    expect(Object.fromEntries(tokenRequest[1].body)).toMatchObject({ code_verifier: challenge.pkceVerifier,
      client_secret: settings.clientSecret, redirect_uri: settings.redirectUri });
    expect(transport.mock.calls[1][0]).toBe("https://api.github.com/user");
    expect(transport.mock.calls[1][1].headers.Authorization).toBe("Bearer provider-secret");
    expect(transport.mock.calls.every(([, input]) => input.redirect === "error")).toBe(true);
    expect(JSON.stringify(result)).not.toMatch(/provider-secret|refresh-secret|private@example/);
  });
  it.each([{ id: 1, login: "sharpninja" }, { id: 16146732, login: "another" }, { id: "16146732", login: "sharpninja" }, {}])("rejects unapproved identity %j", async user => {
    const transport = vi.fn().mockResolvedValueOnce(Response.json({ token_type: "bearer", access_token: "fixture" })).mockResolvedValueOnce(Response.json(user));
    expect((await new GithubAdminProvider(settings, transport).verify(callback)).ok).toBe(false);
  });
  it.each([{ ...callback, state: "forged" }, { ...callback, pkceVerifier: "short" }, { ...callback, code: "" }])("rejects malformed transaction before provider calls", async input => {
    const transport = vi.fn();
    expect((await new GithubAdminProvider(settings, transport).verify(input)).ok).toBe(false);
    expect(transport).not.toHaveBeenCalled();
  });
  it.each([Response.json({ error: "bad_verification_code" }), new Response(null, { status: 502 }), Response.json({ token_type: "other", access_token: "fixture" })])("fails closed on token endpoint errors", async response => {
    const transport = vi.fn().mockResolvedValue(response);
    expect((await new GithubAdminProvider(settings, transport).verify(callback)).ok).toBe(false);
    expect(transport).toHaveBeenCalledTimes(1);
  });
  it("rejects network failures without returning provider details", async () => {
    const transport = vi.fn().mockRejectedValue(new Error("private-provider-detail"));
    expect(await new GithubAdminProvider(settings, transport).verify(callback)).toEqual({ ok: false, error: { code: "NOT_AUTHENTICATED" } });
  });
});

import { beforeEach, expect, it, vi } from "vitest";
import { failure, success } from "../../src/domain/result";
const service = vi.hoisted(() => ({ beginLogin: vi.fn(), completeLogin: vi.fn(), session: vi.fn(), logout: vi.fn() }));
vi.mock("../../src/infrastructure/runtime", () => ({ getAdminIdentityService: () => service }));
import { githubCallback, githubLogin } from "../../src/web/github-auth-http";
import { GET, DELETE } from "../../src/app/api/admin/session/route";
const origin = "https://wordpairs.test";
const token = "a".repeat(43);
const request = (path: string, method = "GET", cookie = `wp_admin=${token}`, source = origin) => new Request(origin + path, { method, headers: { Cookie: cookie, Origin: source } });
beforeEach(() => { vi.stubEnv("WORDPAIRS_ORIGIN", origin); Object.values(service).forEach(mock => mock.mockReset()); });
it("login binds its challenge to a separate secure admin cookie", async () => {
 service.beginLogin.mockResolvedValue(success({ url: "https://github.com/login/oauth/authorize?state=server", browserToken: token }));
 const response = await githubLogin(request("/api/auth/github/login"));
 expect(response.status).toBe(302);
 expect(response.headers.get("Location")).toContain("https://github.com/login/oauth/authorize");
 expect(response.headers.get("Set-Cookie")).toContain(`wp_admin_login=${token}`);
 expect(response.headers.get("Set-Cookie")).toMatch(/HttpOnly; SameSite=Lax; Max-Age=600; Secure/);
 expect(response.headers.get("Cache-Control")).toBe("no-store");
});
it("successful callback sets only the admin session and clears the one-time challenge cookie", async () => {
 service.completeLogin.mockResolvedValue(success({ sessionToken: token }));
 const response = await githubCallback(request("/api/auth/github/callback?code=c&state=s", "GET", `wp_admin_login=${token}; wp_session=guest`));
 expect(service.completeLogin).toHaveBeenCalledWith(token, "c", "s");
 expect(response.headers.get("Location")).toBe(origin + "/admin");
 const cookies = response.headers.get("Set-Cookie")!;
 expect(cookies).toContain("wp_admin_login=;");
 expect(cookies).toContain(`wp_admin=${token}`);
 expect(cookies).not.toContain("wp_session");
});
it.each(["?code=a&code=b&state=s", "?code=c&state=a&state=b", "?error=denied&code=c&state=s"])("malformed or denied callback fails closed: %s", async query => {
 service.completeLogin.mockResolvedValue(failure("NOT_AUTHENTICATED"));
 const response = await githubCallback(request("/api/auth/github/callback" + query, "GET", "wp_session=guest"));
 const [,code,state] = service.completeLogin.mock.calls[0];
 expect(service.completeLogin.mock.calls[0][0]).toBeNull();
 expect(code === null || state === null).toBe(true);
 expect(response.headers.get("Location")).toBe(origin + "/admin?auth=failed");
 expect(response.headers.get("Set-Cookie")).not.toContain("wp_admin=" + token);
});
it("admin session ignores the guest cookie and exposes neither roles nor user delegation", async () => {
 const profile = { id: "owner", kind: "member", alias: "Owner" };
 service.session.mockResolvedValue(success({ profile }));
 const response = await GET(request("/api/admin/session", "GET", `wp_session=guest; wp_admin=${token}`));
 expect(service.session).toHaveBeenCalledWith(token);
 expect(response.headers.get("Cache-Control")).toBe("no-store");
 const body = await response.json();
 expect(body.permissions).toEqual(["moderate", "manage-content", "resolve-appeals"]);
 expect(body.profile).toEqual(profile);
 expect(body.roles).toBeUndefined();
 expect(body.sessionToken).toBeUndefined();
});
it("logout is same-origin, revokes the admin namespace and preserves the guest cookie", async () => {
 service.logout.mockResolvedValue(success(undefined));
 expect((await DELETE(request("/api/admin/session", "DELETE", `wp_admin=${token}`, "https://evil.test"))).status).toBe(403);
 expect(service.logout).not.toHaveBeenCalled();
 const response = await DELETE(request("/api/admin/session", "DELETE", `wp_admin=${token}; wp_session=guest`));
 expect(service.logout).toHaveBeenCalledWith(token);
 expect(response.status).toBe(204);
 expect(response.headers.get("Set-Cookie")).toContain("wp_admin=;");
 expect(response.headers.get("Set-Cookie")).not.toContain("wp_session");
});

