import { PostgresCatalogRepository } from "../../src/infrastructure/catalog-repository";
import { PostgresContentRepository } from "../../src/infrastructure/content-repository";
import { PostgresIdentityRepository } from "../../src/infrastructure/identity-repository";
import { secrets } from "../../src/infrastructure/secrets";

const url = process.env.WORDPAIRS_TEST_DATABASE_URL;
if (!url || new URL(url).hostname !== "127.0.0.1")
  throw new Error("Disposable database required");
const admin = new Pool({ connectionString: url, ssl: false });
const pool = new Pool({
  connectionString: url,
  ssl: false,
  options: "-c role=service_role",
  max: 5,
});
const ids = { next: () => `admin-${randomUUID()}` };
const fixtureNow = Date.now();
const clock = { now: () => fixtureNow };
const identity = new IdentityService(
  new PostgresIdentityRepository(pool),
  secrets,
  ids,
  { integer: (min) => min },
  clock,
  null,
);
const people: string[] = [];
const tokens: string[] = [];
let runtimePool: Pool | null = null;
// Only the TLS connection factory is replaced for the disposable plaintext
// database. The route, composition, identity, authorization and SQL are real.
vi.mock("../../src/infrastructure/postgres-pool", async () => {
  const { Pool: TestPool } = await import("pg");
  return {
    createSupabasePool: (connectionString: string) =>
      new TestPool({
        connectionString,
        ssl: false,
        options: "-c role=service_role",
        max: 3,
      }),
  };
});
const value = <T>(r: Result<T>) => {
  if (!r.ok) throw new Error(JSON.stringify(r));
  return r.value;
};
let root: string;
let moderator: string;
let player: string;
let a: string;
let b: string;
let access: AccessService;
let content: ContentService;
let contentRepository: PostgresContentRepository;
const catalog = new PostgresCatalogRepository(pool);
const roleCommand = async (
  actorId: string,
  input: RoleChange,
  service = access,
) => ({
  aggregateId: "access-control",
  actorId,
  commandId: ids.next(),
  requestDigest: secrets.hash(JSON.stringify(input)),
  expectedVersion: value(await service.view(actorId)).version,
});
const role = async (
  profileId: string,
  managedRole: RoleChange["role"],
  grant = true,
) => {
  const input = {
    profileId,
    role: managedRole,
    grant,
    reason: "Integration role change",
  };
  return access.act(await roleCommand(root, input), input);
};
async function editorial(actorId: string, action: ContentAction) {
  return content.act(
    {
      aggregateId: CONTENT_ID,
      actorId,
      commandId: ids.next(),
      requestDigest: secrets.hash(JSON.stringify(action)),
      expectedVersion: value(await contentRepository.read(root)).state.version,
    },
    action,
  );
}
beforeAll(async () => {
  for (let n = 0; n < 5; n++) {
    const guest = value(await identity.guest(null));
    people.push(guest.profile.id);
    tokens.push(guest.sessionToken);
  }
  [root, moderator, player, a, b] = people;
  access = new AccessService(new PostgresAccessRepository(pool, [root]));
  contentRepository = new PostgresContentRepository(pool, clock.now, [root]);
  content = new ContentService(contentRepository, clock, ids);
});
afterAll(async () => {
  try {
    await admin.query(
      "delete from wordpairs.audit_events where target_id='content-catalog';delete from wordpairs.idempotency_records where aggregate_id='content-catalog';delete from wordpairs.outbox_events where aggregate_id='content-catalog'",
    );
    await admin.query(
      "update wordpairs.aggregates set version=0,state=$1::jsonb where kind='moderation' and id='content-catalog'",
      [JSON.stringify(emptyContent())],
    );
    await admin.query(
      "begin;alter table wordpairs.word_pairs disable trigger immutable_pair;alter table wordpairs.accepted_answers disable trigger immutable_accepted_answer;delete from wordpairs.catalog_exclusions where pair_id='opposites-01' and pair_version>0;delete from wordpairs.accepted_answers where (pair_id='opposites-01' and pair_version>0) or pair_id like 'admin-http-%';delete from wordpairs.word_pairs where (id='opposites-01' and version>0) or id like 'admin-http-%';alter table wordpairs.word_pairs enable trigger immutable_pair;alter table wordpairs.accepted_answers enable trigger immutable_accepted_answer;commit;update wordpairs.catalog_revision set revision=revision+1",
    );
    await admin.query(
      "delete from wordpairs.access_commands where actor_id=any($1::text[])",
      [people],
    );
    await admin.query(
      "delete from wordpairs.access_audit where actor_id=any($1::text[]) or profile_id=any($1::text[])",
      [people],
    );
    for (const table of ["profile_roles", "sessions", "guest_credentials"])
      await admin.query(
        `delete from wordpairs.${table} where profile_id=any($1::text[])`,
        [people],
      );
    await admin.query(
      "delete from wordpairs.nominations where candidate_id in(select id from wordpairs.moderation_cases where proposer_id=any($1::text[]))",
      [people],
    );
    await admin.query(
      "delete from wordpairs.moderation_cases where proposer_id=any($1::text[])",
      [people],
    );
    await admin.query(
      "delete from wordpairs.outbox_events where aggregate_kind='profile' and aggregate_id=any($1::text[])",
      [people],
    );
    await admin.query(
      "delete from wordpairs.aggregates where kind='profile' and id=any($1::text[])",
      [people],
    );
    await admin.query(
      "delete from wordpairs.profiles where id=any($1::text[])",
      [people],
    );
  } finally {
    await Promise.all([pool.end(), admin.end(), runtimePool?.end()]);
    vi.unstubAllEnvs();
  }
});

it("real HTTP composition isolates guest privileges and authenticates only the fixed GitHub owner against PostgreSQL", async () => {
  vi.stubEnv("WORDPAIRS_DATABASE_URL", url);
  vi.stubEnv("WORDPAIRS_ADMIN_PROFILE_IDS", root);
  vi.stubEnv("WORDPAIRS_ORIGIN", "https://admin-fixture.test");
  vi.stubEnv("WORDPAIRS_GITHUB_CLIENT_ID", "fixture-client");
  vi.stubEnv("WORDPAIRS_GITHUB_CLIENT_SECRET", "fixture-secret");
  const provider = vi.fn(async (input: string | URL | Request) => {
    const target = String(input);
    if (target === "https://github.com/login/oauth/access_token") return Response.json({ access_token: "fixture-provider-token", token_type: "bearer" });
    if (target === "https://api.github.com/user") return Response.json({ id: 16146732, login: "sharpninja" });
    throw new Error("Unexpected external request in isolated fixture");
  });
  vi.stubGlobal("fetch", provider);
  try {
    const runtime = await import("../../src/infrastructure/runtime");
    runtimePool = runtime.getDatabasePool();
    const users = await import("../../src/app/api/admin/users/route");
    const contents = await import("../../src/app/api/content/route");
    const session = await import("../../src/app/api/session/route");
    const adminSession = await import("../../src/app/api/admin/session/route");
    const auth = await import("../../src/web/github-auth-http");
    const request = (path: string, cookies = `wp_session=${tokens[0]}`, body?: unknown, method?: string) =>
      new Request("https://admin-fixture.test" + path, { method: method ?? (body ? "POST" : "GET"),
        headers: { Cookie: cookies, Origin: "https://admin-fixture.test", "Content-Type": "application/json" },
        ...(body ? { body: JSON.stringify(body) } : {}) });
    expect((await users.GET(request("/api/admin/users"))).status).toBe(404);
    expect((await users.POST(request("/api/admin/users", undefined, { role: "admin", grant: true }))).status).toBe(404);
    expect((await contents.GET(request("/api/content"))).status).toBe(401);
    const publicGuest = await (await session.GET(request("/api/session"))).json();
    expect(publicGuest.permissions).toEqual([]);
    const begin = await auth.githubLogin(request("/api/auth/github/login"));
    expect(begin.status).toBe(302);
    const browserToken = begin.headers.get("Set-Cookie")!.match(/wp_admin_login=([A-Za-z0-9_-]{43})/)![1];
    const state = new URL(begin.headers.get("Location")!).searchParams.get("state")!;
    const callbackPath = "/api/auth/github/callback?code=fixture-code&state=" + encodeURIComponent(state);
    const cookies = `wp_session=${tokens[0]}; wp_admin_login=${browserToken}`;
    const callback = await auth.githubCallback(request(callbackPath, cookies));
    expect(callback.headers.get("Location")).toBe("https://admin-fixture.test/admin");
    const adminToken = callback.headers.get("Set-Cookie")!.match(/\bwp_admin=([A-Za-z0-9_-]{43})/)![1];
    expect(callback.headers.get("Set-Cookie")).not.toContain("wp_session=");
    expect((await adminSession.GET(request("/api/admin/session", `wp_admin=${tokens[0]}`))).status).toBe(401);
    expect((await session.GET(request("/api/session", `wp_session=${adminToken}`))).status).toBe(401);
    const current = await adminSession.GET(request("/api/admin/session", `wp_admin=${adminToken}`));
    expect(current.status).toBe(200);
    const owner = await current.json();
    people.push(owner.profile.id);
    expect(owner.permissions).toEqual(["moderate", "manage-content", "resolve-appeals"]);
    expect(owner.profile.kind).toBe("member");
    expect(JSON.stringify(owner)).not.toMatch(/fixture-provider-token|fixture-secret/);
    const editor = await contents.GET(request("/api/content", `wp_admin=${adminToken}`));
    expect(editor.status).toBe(200);
    const editable = await editor.json();
    expect(editable.canModerate).toBe(true);
    const original = value(await catalog.pair("opposites-01", 0));
    const pair = { ...original, id: `admin-http-${randomUUID()}`, selectable: undefined, version: 0, prompt: "HTTP authored pair", hints: ["First HTTP clue", "Second HTTP clue", "Third HTTP clue"] };
    const save = { action: "save-pair", pair, reason: "Verify owner-only server composition", expectedProfileId: owner.profile.id, expectedVersion: editable.version, commandId: ids.next() };
    expect((await contents.POST(request("/api/content", `wp_admin=${adminToken}`, save))).status).toBe(200);
    expect(value(await catalog.pair(pair.id, 0)).hints).toEqual(pair.hints);
    const replay = await auth.githubCallback(request(callbackPath, cookies));
    expect(replay.headers.get("Location")).toBe("https://admin-fixture.test/admin?auth=failed");
    expect(replay.headers.get("Set-Cookie")).not.toContain("wp_admin=" + adminToken);
    expect(provider).toHaveBeenCalledTimes(2);
    expect((await adminSession.DELETE(request("/api/admin/session", `wp_admin=${adminToken}`, undefined, "DELETE"))).status).toBe(204);
    expect((await adminSession.GET(request("/api/admin/session", `wp_admin=${adminToken}`))).status).toBe(401);
    expect((await contents.GET(request("/api/content", `wp_admin=${adminToken}`))).status).toBe(401);
    expect((await session.GET(request("/api/session"))).status).toBe(200);
  } finally { vi.unstubAllGlobals(); }
});
