#Requires -Version 7.0
# Review step 8: suite completeness and chronology (read-only).
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
$ws = '<repo>'
Set-Location -LiteralPath $ws
$dir = Join-Path $ws 'docs/evidence/hosting/guest-admin-validation'
function Get-JUnitFiles([string]$Path) {
    [xml]$x = [IO.File]::ReadAllText($Path)
    return @($x.SelectNodes('//testcase') | ForEach-Object { $_.GetAttribute('classname') } | Sort-Object -Unique)
}
$unitFiles = Get-JUnitFiles (Join-Path $dir 'unit.xml')
$pgFiles = Get-JUnitFiles (Join-Path $dir 'postgres.xml')
$adminPg = Get-JUnitFiles (Join-Path $dir 'admin-identity-postgres.xml')
$browserFiles = Get-JUnitFiles (Join-Path $dir 'browser.xml')
$tracked = @(git ls-files 'tests')
$unitCandidates = @($tracked | Where-Object { $_ -match '\.test\.(ts|tsx)$' })
$integrationCandidates = @($tracked | Where-Object { $_ -match '\.integration\.ts$' })
$browserCandidates = @($tracked | Where-Object { $_ -match '\.spec\.ts$' })
Write-Output ("UNIT: trackedTestFiles={0} filesInJUnit={1}" -f $unitCandidates.Count, $unitFiles.Count)
Compare-Object $unitCandidates $unitFiles | ForEach-Object { Write-Output ("  UNIT-DIFF {0} {1}" -f $_.SideIndicator, $_.InputObject) }
Write-Output ("POSTGRES: trackedIntegrationFiles={0} filesInJUnit={1}" -f $integrationCandidates.Count, $pgFiles.Count)
Compare-Object $integrationCandidates $pgFiles | ForEach-Object { Write-Output ("  PG-DIFF {0} {1}" -f $_.SideIndicator, $_.InputObject) }
Write-Output ("ADMIN-PG files: {0}" -f ($adminPg -join ', '))
Write-Output ("BROWSER: trackedSpecFiles={0} classnamesInJUnit={1}" -f $browserCandidates.Count, $browserFiles.Count)
$browserFiles | ForEach-Object { Write-Output ("  BROWSER-CLASS {0}" -f $_) }
$browserCandidates | ForEach-Object { Write-Output ("  BROWSER-SPEC {0}" -f $_) }
Write-Output '---- vitest/playwright configs'
foreach ($cfg in @(git ls-files | Where-Object { $_ -match '^(vitest|playwright)[^/]*\.(ts|mts|js)$' })) { Write-Output ("CONFIG {0}" -f $cfg) }
Write-Output '---- chronology (local time): mtimes of product files changed in range'
$base = '8e2f62417e0fe46cefd884e8a61024b12860a2cf'
$head = '437c501c58c7dfa96ee576f445d225f2dd62a0bd'
$changed = @(git diff --name-only --diff-filter=AMR $base $head | Where-Object { $_ -match '^(src|public|tests|scripts|next\.config)' })
$unitRun = [datetime]'2026-10-28T19:27:53'
$browserRun = [datetime]'2026-10-28T19:42:45'
$late = foreach ($f in $changed) {
    $t = (Get-Item -LiteralPath $f).LastWriteTime
    [pscustomobject]@{ File = $f; Mtime = $t.ToString('s'); AfterUnit = ($t -gt $unitRun); AfterBrowser = ($t -gt $browserRun) }
}
$late | Sort-Object Mtime -Descending | Select-Object -First 15 | ForEach-Object { Write-Output ("  {0} {1} afterUnit={2} afterBrowser={3}" -f $_.Mtime, $_.File, $_.AfterUnit, $_.AfterBrowser) }
Write-Output ("  changedProductFiles={0} afterUnitRun={1} afterBrowserRun={2}" -f $changed.Count, @($late | Where-Object AfterUnit).Count, @($late | Where-Object AfterBrowser).Count)
Write-Output '---- evidence log heads/tails'
foreach ($log in @('build.log', 'lint.log', 'unit.log', 'browser.log', 'postgres.log', 'admin-identity-postgres.log', 'card-insets.log')) {
    $p = Join-Path $dir $log
    $item = Get-Item -LiteralPath $p
    $lines = @(Get-Content -LiteralPath $p)
    Write-Output ("== {0} mtime={1} lines={2}" -f $log, $item.LastWriteTime.ToString('s'), $lines.Count)
    $lines | Select-Object -First 4 | ForEach-Object { Write-Output ("  HEAD {0}" -f $_) }
    $lines | Select-Object -Last 6 | ForEach-Object { Write-Output ("  TAIL {0}" -f $_) }
}

