#Requires -Version 7.0
# Review step 9: summarize retained run-history logs (read-only).
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
$dir = '<repo>/docs/evidence/hosting/guest-admin-validation/run-history'
$patterns = '(\d+ (passed|failed|flaky|skipped|did not run))|Tests\s+\d+|Test Files|✘|FAIL\b|×|Error:|expected|Start at|JUNIT report'
foreach ($f in (Get-ChildItem -LiteralPath $dir -File | Sort-Object LastWriteTime)) {
    $lines = @(Get-Content -LiteralPath $f.FullName)
    Write-Output ("== {0} mtime={1} lines={2}" -f $f.Name, $f.LastWriteTime.ToString('s'), $lines.Count)
    $hits = @($lines | Select-String -Pattern $patterns | Select-Object -First 14)
    foreach ($h in $hits) {
        $t = $h.Line.Trim()
        if ($t.Length -gt 220) { $t = $t.Substring(0, 220) }
        Write-Output ("  {0}: {1}" -f $h.LineNumber, $t)
    }
}

